let w = window_rect("AutoFlow Manual Acceptance Harness");
if w.found {
    let hit = wait_image("manual-vision-target.png", w.x, w.y, w.width, w.height, 0.90, 3000, 150);
    if hit.found {
        stop_with_message("MANUAL_TEST_IMAGE_SUCCESS", "MANUAL_TEST_IMAGE_HIT");
    } else {
        stop_with_message("MANUAL_TEST_IMAGE_NOT_FOUND", "MANUAL_TEST_IMAGE_NOT_FOUND_OR_TIMEOUT");
    }
}
